const $=s=>document.querySelector(s), app=$('#app'),THEME_KEY='crmTheme';
const currentTheme=()=>document.documentElement.dataset.theme||'light';
function applyTheme(theme){const next=theme==='dark'?'dark':'light';document.documentElement.dataset.theme=next;document.documentElement.style.colorScheme=next;localStorage.setItem(THEME_KEY,next);const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.content=next==='dark'?'#0e1117':'#f4f5f7'}
function initTheme(){const saved=localStorage.getItem(THEME_KEY),system=window.matchMedia?.('(prefers-color-scheme: dark)').matches?'dark':'light';applyTheme(saved||system)}
function themeControl(){const dark=currentTheme()==='dark';return `<button type="button" class="theme-toggle" data-theme-toggle title="${dark?'Включить светлую тему':'Включить тёмную тему'}" aria-pressed="${dark}"><span>${dark?'☀':'☾'}</span><em>${dark?'Светлая тема':'Тёмная тема'}</em></button>`}
function bindTheme(){document.querySelectorAll('[data-theme-toggle]').forEach(b=>b.onclick=()=>{applyTheme(currentTheme()==='dark'?'light':'dark');state.me?shellRefresh():login()})}
function shellRefresh(){if(state.view==='dashboard')renderDashboard();else if(state.view==='risks')renderRisks();else if(state.view==='sales')renderSales();else if(state.view==='lead')renderLead();else if(state.view==='project')renderProject();else renderAccount()}
initTheme();
const state={me:null,users:[],dashboard:null,sales:null,lead:null,project:null,view:'dashboard',tab:'overview'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=d=>{if(!d)return'—';const raw=String(d),iso=/(?:Z|[+-]\d\d:\d\d)$/u.test(raw)?raw:raw.replace(' ','T')+'Z';return new Date(iso).toLocaleString('ru-RU',{day:'2-digit',month:'short',year:'numeric'})};
const daysUntil=d=>{if(!d)return null;const target=new Date(`${String(d).slice(0,10)}T00:00:00`),today=new Date();today.setHours(0,0,0,0);return Math.round((target-today)/86400000)};
const taskHot=t=>t.status==='blocked'||['high','urgent'].includes(t.priority)||(daysUntil(t.due_date)!==null&&daysUntil(t.due_date)<=2);
const safeUrl=u=>/^https?:\/\//i.test(String(u||''))?String(u):'';
const labels={lead:'Лид',sold:'Продан',handoff:'Передача',preparing:'Подготовка',review:'На проверке',ready:'Готов к запуску',launched:'Запущен',management:'Ведение',paused:'Пауза',completed:'Завершён',not_transferred:'Не передан',checking:'На проверке',accepted:'Принят',returned:'На уточнение',none:'Нет',low:'Низкий',medium:'Средний',normal:'Обычный',high:'Высокий',urgent:'Срочный',stop:'СТОП',backlog:'План',doing:'В работе',review_task:'Проверка',done:'Готово',blocked:'Блок',todo:'Не начато',na:'Не применимо',open:'Открыта',resolved:'Закрыта',new:'Новый',contacted:'Связались',qualified:'Квалифицирован',meeting:'Созвон',proposal:'КП отправлено',won:'Продан',lost:'Проигран',unqualified:'Не квалифицирован',bad_fit:'Не подходит',confirmed:'Подтверждено',confirmed_zero:'Подтверждённый ноль',unavailable:'Недоступно',ok:'Норма',attention:'Внимание',critical:'Критично',planned:'Запланировано',approval_required:'Нужно согласование',applied:'Выполнено',rejected:'Отклонено',rolled_back:'Отменено'};
const salesStages=[['new','Новые'],['contacted','В работе'],['qualified','Квалифицированы'],['meeting','Созвон'],['proposal','КП'],['won','Проданы'],['lost','Проиграны']];
const tag=(v,cls='')=>`<span class="tag ${cls||(['high','stop','blocked'].includes(v)?'danger':['medium','doing','checking'].includes(v)?'warn':['accepted','done','launched','management'].includes(v)?'ok':'')}">${esc(labels[v]||v||'—')}</span>`;
async function api(path,opt={}){const r=await fetch(path,{headers:{'content-type':'application/json',...(opt.headers||{})},...opt});let x={};try{x=await r.json()}catch{}if(!r.ok)throw new Error(x.error||`Ошибка ${r.status}`);return x}
function toast(msg,error=false){const n=document.createElement('div');n.className='toast'+(error?' error':'');n.textContent=msg;$('#toast').append(n);setTimeout(()=>n.remove(),3500)}
function formData(form){return Object.fromEntries(new FormData(form).entries())}
function login(){app.innerHTML=`<div class="login-page"><section class="login-art"><div class="brand"><img class="brand-logo" src="https://static.tildacdn.com/tild3538-6363-4639-a130-633635396361/Logo.svg" alt="DigitalRed"><span>CRM</span></div><div><h1>Проекты без ручного контроля собственника.</h1><p>Передача, производство, запуск, доказательства и отчётность — в одном обязательном процессе.</p></div><small>DigitalRed — внутренняя CRM рекламного агентства</small></section><section class="login-box"><form id="login">${themeControl()}<h2>Вход в DigitalRed CRM</h2><p class="sub">Используйте выданные персональные данные.</p><div class="field"><label>Логин</label><input name="login" autocomplete="username" required></div><div class="field"><label>Пароль</label><input type="password" name="password" autocomplete="current-password" required></div><button class="btn full">Войти</button></form></section></div>`;bindTheme();$('#login').onsubmit=async e=>{e.preventDefault();try{await api('api/login',{method:'POST',body:JSON.stringify(formData(e.target))});await init()}catch(x){toast(x.message,true)}}}
function shell(title,content){
  const collapsed=localStorage.getItem('sidebarCollapsed')==='1';
  const sales=state.me.role==='owner'?`<button data-view="sales" class="${['sales','lead'].includes(state.view)?'active':''}" title="Продажи"><span>↗</span><em>Продажи</em></button>`:'';
  const back=state.project?'<button class="btn secondary small" data-back="dashboard">← Производство</button>':state.lead?'<button class="btn secondary small" data-back="sales">← Воронка</button>':'';
  const role=state.me.role==='owner'?'Собственник':state.me.role==='manager'?'Проджект':'Исполнитель';
  const initial=String(state.me.name||'И').trim().slice(0,1).toUpperCase();
  app.innerHTML=`<div class="shell ${collapsed?'sidebar-collapsed':''}"><aside class="sidebar" id="side"><div class="brand"><img class="brand-logo" src="https://static.tildacdn.com/tild3538-6363-4639-a130-633635396361/Logo.svg" alt="DigitalRed"><span class="brand-crm">CRM</span><b class="brand-mini">DR</b></div><nav class="nav">${sales}<button data-view="dashboard" class="${['dashboard','project'].includes(state.view)?'active':''}" title="Производство"><span>◫</span><em>Производство</em></button><button data-view="risks" class="${state.view==='risks'?'active':''}" title="Контроль"><span>!</span><em>Контроль</em></button></nav>${themeControl()}<button class="side-toggle" id="sideToggle" title="${collapsed?'Развернуть меню':'Свернуть меню'}"><span>${collapsed?'›':'‹'}</span><em>${collapsed?'Развернуть':'Свернуть'}</em></button><div class="userbox"><button type="button" class="user-profile ${state.view==='account'?'active':''}" id="userProfile" title="Открыть профиль"><span class="user-avatar">${esc(initial)}</span><span class="user-copy"><strong>${esc(state.me.name)}</strong><small>${role}</small></span></button><button class="logout" id="logout">Выйти</button></div></aside><button class="menu-scrim" id="menuScrim" aria-label="Закрыть меню"></button><main class="main"><header class="topbar"><button class="btn secondary small mobile-menu" id="menu" aria-label="Открыть меню">☰</button><h1>${esc(title)}</h1><div>${back}</div></header><div class="content">${content}</div></main></div>`;
  bindTheme();
  document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));
  $('#userProfile').onclick=()=>navigate('account');
  $('#logout').onclick=async()=>{await api('api/logout',{method:'POST'});login()};
  const setMenu=open=>{$('#side').classList.toggle('open',open);$('#menuScrim').classList.toggle('open',open)};
  $('#menu').onclick=()=>setMenu(!$('#side').classList.contains('open'));
  $('#menuScrim').onclick=()=>setMenu(false);
  $('#sideToggle').onclick=()=>{const shell=$('.shell'),next=!shell.classList.contains('sidebar-collapsed');shell.classList.toggle('sidebar-collapsed',next);localStorage.setItem('sidebarCollapsed',next?'1':'0');$('#sideToggle span').textContent=next?'›':'‹';$('#sideToggle em').textContent=next?'Развернуть':'Свернуть';$('#sideToggle').title=next?'Развернуть меню':'Свернуть меню'};
  document.querySelectorAll('[data-back]').forEach(b=>b.onclick=()=>navigate(b.dataset.back));
}
async function navigate(view,id){try{state.view=view;if(view==='project'){state.lead=null;state.project=await api(`api/projects/${id}/all`);return renderProject()}if(view==='lead'){state.project=null;state.lead=await api(`api/leads/${id}`);return renderLead()}state.project=null;state.lead=null;if(view==='dashboard'||view==='risks'){state.dashboard=await api('api/dashboard');return view==='dashboard'?renderDashboard():renderRisks()}if(view==='sales'){state.sales=await api('api/sales/dashboard');return renderSales()}if(view==='account')renderAccount()}catch(e){toast(e.message||'Не удалось открыть раздел',true)}}
function projectTile(p){const due=p.next_task_due||p.next_action_due||p.launch_deadline,reportDue=!p.next_report||daysUntil(p.next_report)<0,contactDue=p.next_client_contact&&daysUntil(p.next_client_contact)<=0,noAction=!String(p.next_action||'').trim(),hot=p.urgent_tasks||p.overdue||p.open_escalations||reportDue||contactDue||noAction||['high','stop'].includes(p.risk);return `<article class="project-tile ${hot?'hot':''}" data-p="${p.id}" tabindex="0"><div class=tile-head><div><h3>${esc(p.client)}</h3><p>${esc(p.service)}</p></div>${tag(p.stage)}</div><div class=tile-tags>${p.risk!=='none'?tag(p.risk):''}${p.overdue?tag(`${p.overdue} просрочено`,'danger'):''}${p.open_escalations?tag(`${p.open_escalations} эскалац.`,'danger'):''}${reportDue?tag('Отчёт нужен','warn'):''}${contactDue?tag('Связаться','warn'):''}${noAction?tag('Нет действия','danger'):''}</div><div class=tile-action><small>Следующее действие</small><strong>${esc(p.next_action||'Не задано — проект выпадет из управления')}</strong></div><div class=tile-meta><span>Задачи: <b>${p.open_tasks||0}</b></span><span>Ближайший срок: <b>${fmt(due)}</b></span><span>Менеджер: <b>${esc(p.manager_name||'—')}</b></span><span>Отчёт: <b>${fmt(p.next_report)}</b></span></div></article>`}
function drawProjects(){const q=$('#projectSearch').value.trim().toLowerCase(),scope=$('#projectScope').value,sort=$('#projectSort').value;let ps=state.dashboard.projects.filter(p=>`${p.client} ${p.service} ${p.next_action||''} ${p.manager_name||''}`.toLowerCase().includes(q));if(scope==='work')ps=ps.filter(p=>!['paused','completed'].includes(p.stage));if(scope==='attention')ps=ps.filter(p=>p.overdue||p.urgent_tasks||p.open_escalations||!p.next_report||daysUntil(p.next_report)<0||!String(p.next_action||'').trim()||['high','stop'].includes(p.risk));if(scope==='reports')ps=ps.filter(p=>!p.next_report||daysUntil(p.next_report)<0);if(scope==='contacts')ps=ps.filter(p=>p.next_client_contact&&daysUntil(p.next_client_contact)<=0);if(scope==='paused')ps=ps.filter(p=>p.stage==='paused');if(sort==='name')ps.sort((a,b)=>a.client.localeCompare(b.client,'ru'));if(sort==='report')ps.sort((a,b)=>String(a.next_report||'0000').localeCompare(String(b.next_report||'0000')));if(sort==='deadline')ps.sort((a,b)=>String(a.next_task_due||a.launch_deadline||'9999').localeCompare(String(b.next_task_due||b.launch_deadline||'9999')));$('#projectList').innerHTML=ps.map(projectTile).join('')||'<div class="card empty">По выбранному фильтру проектов нет</div>';document.querySelectorAll('[data-p]').forEach(r=>{r.onclick=()=>navigate('project',r.dataset.p);r.onkeydown=e=>{if(e.key==='Enter')navigate('project',r.dataset.p)}})}
function renderDashboard(){const d=state.dashboard,c=d.counts;shell('Производство',`<div class="toolbar"><div><h2>Проекты в работе</h2><div class="muted">Приоритеты: просрочки, клиентские контакты, отчёты, блокировки и проекты без следующего действия</div></div><div class=project-actions><button class="btn" id="newProject">+ Проект</button></div></div><div class="stats production-stats"><div class="stat"><small>Проектов</small><strong>${c.total||0}</strong></div><div class="stat"><small>На ведении</small><strong>${c.active||0}</strong></div><div class="stat danger"><small>Просрочено задач</small><strong>${c.overdue||0}</strong></div><div class="stat danger"><small>Отчёт просрочен</small><strong>${c.reports_due||0}</strong></div><div class="stat"><small>Связаться сегодня</small><strong>${c.contacts_due||0}</strong></div><div class="stat danger"><small>Без действия</small><strong>${c.without_action||0}</strong></div></div><section class=portfolio-tools><input id=projectSearch placeholder="Поиск по клиенту, услуге, менеджеру или действию"><select id=projectScope><option value=all>Все проекты</option><option value=work>В работе</option><option value=attention>Требуют внимания</option><option value=reports>Нет свежего отчёта</option><option value=contacts>Связаться сегодня</option><option value=paused>Пауза</option></select><select id=projectSort><option value=priority>Сначала проблемные</option><option value=deadline>По ближайшему сроку</option><option value=report>По дате отчёта</option><option value=name>По названию</option></select></section><div class=project-grid id=projectList></div>`);$('#projectSearch').oninput=drawProjects;$('#projectScope').onchange=drawProjects;$('#projectSort').onchange=drawProjects;$('#newProject').onclick=()=>projectModal();drawProjects()}
function renderRisks(){const ps=state.dashboard.projects.filter(p=>p.risk!=='none'||p.overdue||p.handoff_open||p.launch_open);shell('Риски и сроки',`<div class="toolbar"><div><h2>Требует внимания</h2><div class="muted">Только проекты с незакрытыми воротами, рисками или просрочкой</div></div></div><section class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Проект</th><th>Риск</th><th>Передача</th><th>Запуск</th><th>Просрочка</th><th>Дедлайн запуска</th></tr></thead><tbody>${ps.map(p=>`<tr class=clickable data-p="${p.id}"><td><b>${esc(p.client)}</b><br><small>${esc(p.service)}</small></td><td>${tag(p.risk)}</td><td>${p.handoff_open} пунктов</td><td>${p.launch_open} проверок</td><td>${p.overdue} задач</td><td>${fmt(p.launch_deadline)}</td></tr>`).join('')||'<tr><td colspan=6 class=empty>Критических отклонений нет</td></tr>'}</tbody></table></div></section>`);document.querySelectorAll('[data-p]').forEach(r=>r.onclick=()=>navigate('project',r.dataset.p))}
function leadTile(l){const overdue=!['won','lost'].includes(l.stage)&&l.next_action_due&&daysUntil(l.next_action_due)<0,next=salesStages.findIndex(([id])=>id===l.stage),nextStage=next>=0&&next<salesStages.length-2?salesStages[next+1][0]:'',publicSource=l.source&&!/^Google Таблица «Лиды»$/i.test(l.source)?l.source:'';return `<article class="lead-tile ${overdue?'overdue':''}" data-lead="${l.id}" draggable="true" tabindex="0"><div class=tile-head><div><h3>${esc(l.company)}</h3><p>${esc(l.contact_name||l.phone||'Контакт не заполнен')}</p></div><span class=drag-handle title="Перетащить">⋮⋮</span></div><div class=lead-badges>${tag(l.qualification,l.qualification==='qualified'?'ok':'')}${l.budget?tag(l.budget,'accent'):''}</div><div class=lead-meta>${publicSource?`<span>${esc(publicSource)}</span>`:''}<span>${esc(l.service||'Услуга не указана')}</span></div><div class=tile-action><small>Следующий шаг · ${fmt(l.next_action_due)}</small><strong>${esc(l.next_action||'Не задан — лид теряется')}</strong></div><div class=lead-footer><small>${esc(l.owner_name||'Без ответственного')} · касаний: ${l.activity_count||0}</small>${nextStage?`<button class="lead-advance" data-advance="${l.id}" data-stage="${nextStage}" title="Перевести дальше">→</button>`:''}</div></article>`}
function renderSales(){const s=state.sales,c=s.counts||{};shell('Продажи',`<div class=toolbar><div><h2>Воронка продаж</h2><div class=muted>Перетаскивайте карточки между этапами; продажа автоматически передаётся в производство</div></div><div class=project-actions><button class="btn secondary" id=newSalesCall>+ Созвон</button><button class=btn id=newLead>+ Лид</button></div></div><div class="stats sales-stats"><div class=stat><small>Всего лидов</small><strong>${c.total||0}</strong></div><div class=stat><small>Активные</small><strong>${c.active||0}</strong></div><div class=stat><small>Квалифицированы</small><strong>${c.qualified||0}</strong></div><div class="stat danger"><small>Просрочен контакт</small><strong>${c.overdue||0}</strong></div><div class="stat danger"><small>Без следующего шага</small><strong>${c.without_action||0}</strong></div><div class=stat><small>Проданы</small><strong>${c.won||0}</strong></div></div><section class="portfolio-tools sales-tools"><input id=leadSearch placeholder="Поиск по компании, контакту, телефону, источнику или услуге"><select id=leadScope><option value=all>Все лиды</option><option value=active>Только активные</option><option value=overdue>Просроченные</option><option value=without_action>Без следующего шага</option></select><select id=leadSort><option value=priority>Сначала требующие внимания</option><option value=recent>Сначала обновлённые</option><option value=company>По компании</option></select></section><div class=sales-hint><span>⋮⋮</span> Зажмите карточку и перенесите в нужный столбец. На телефоне используйте стрелку →.</div><div class=sales-board id=salesBoard>${salesStages.map(([id,name])=>`<section class="sales-column sales-column-${id}" data-sales-stage="${id}"><div class=column-head><span>${name}</span><b data-stage-count>0</b></div><div class=lead-list></div></section>`).join('')}</div>`);const move=async(l,stage)=>{if(!l||l.stage===stage)return;if(stage==='won'){convertLeadModal(l);return}if(stage==='lost'){modal('Закрыть как проигранный',`<p class=muted>${esc(l.company)}</p><div class=field><label>Причина проигрыша *</label><textarea name=loss_reason required placeholder="Почему клиент не выбрал нас и что учесть дальше">${esc(l.loss_reason||'')}</textarea></div>`,async x=>{await api(`api/leads/${l.id}`,{method:'PATCH',body:JSON.stringify({stage:'lost',loss_reason:x.loss_reason})});await navigate('sales');toast('Лид закрыт как проигранный')});return}await api(`api/leads/${l.id}`,{method:'PATCH',body:JSON.stringify({stage,qualification:['qualified','meeting','proposal'].includes(stage)?'qualified':l.qualification})});l.stage=stage;if(['qualified','meeting','proposal'].includes(stage))l.qualification='qualified';draw();toast(`Лид перенесён: ${labels[stage]}`)};const draw=()=>{const q=$('#leadSearch').value.trim().toLowerCase(),scope=$('#leadScope').value,sort=$('#leadSort').value;document.querySelectorAll('[data-sales-stage]').forEach(col=>{const stage=col.dataset.salesStage;let rows=s.leads.filter(l=>l.stage===stage&&`${l.company} ${l.contact_name} ${l.phone} ${l.source} ${l.service}`.toLowerCase().includes(q));if(scope==='active')rows=rows.filter(l=>!['won','lost'].includes(l.stage));if(scope==='overdue')rows=rows.filter(l=>l.next_action_due&&daysUntil(l.next_action_due)<0&&!['won','lost'].includes(l.stage));if(scope==='without_action')rows=rows.filter(l=>!String(l.next_action||'').trim()&&!['won','lost'].includes(l.stage));if(sort==='company')rows.sort((a,b)=>a.company.localeCompare(b.company,'ru'));if(sort==='recent')rows.sort((a,b)=>String(b.updated_at).localeCompare(String(a.updated_at)));if(sort==='priority')rows.sort((a,b)=>Number(!String(b.next_action||'').trim())-Number(!String(a.next_action||'').trim())||(daysUntil(a.next_action_due)??9999)-(daysUntil(b.next_action_due)??9999));col.querySelector('[data-stage-count]').textContent=rows.length;col.querySelector('.lead-list').innerHTML=rows.map(leadTile).join('')||'<div class=column-empty>Перетащите лид сюда</div>'});document.querySelectorAll('[data-lead]').forEach(r=>{let dragged=false;r.ondragstart=e=>{dragged=true;r.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/lead-id',r.dataset.lead)};r.ondragend=()=>{r.classList.remove('dragging');document.querySelectorAll('.sales-column').forEach(c=>c.classList.remove('drag-over'));setTimeout(()=>dragged=false,0)};r.onclick=e=>{if(!dragged&&!e.target.closest('button'))navigate('lead',r.dataset.lead)};r.onkeydown=e=>{if(e.key==='Enter')navigate('lead',r.dataset.lead)}});document.querySelectorAll('[data-advance]').forEach(b=>b.onclick=e=>{e.stopPropagation();move(s.leads.find(l=>String(l.id)===b.dataset.advance),b.dataset.stage)});document.querySelectorAll('.sales-column').forEach(col=>{col.ondragover=e=>{e.preventDefault();e.dataTransfer.dropEffect='move';col.classList.add('drag-over')};col.ondragleave=e=>{if(!col.contains(e.relatedTarget))col.classList.remove('drag-over')};col.ondrop=e=>{e.preventDefault();col.classList.remove('drag-over');move(s.leads.find(l=>String(l.id)===e.dataTransfer.getData('text/lead-id')),col.dataset.salesStage)}})};$('#leadSearch').oninput=draw;$('#leadScope').onchange=draw;$('#leadSort').onchange=draw;$('#newLead').onclick=()=>leadModal();$('#newSalesCall').onclick=()=>callIntakeModal();draw()}
function renderLead(){const x=state.lead,l=x.lead,canConvert=!l.converted_project_id&&!['won','lost'].includes(l.stage);shell(l.company,`<div class=project-header><div><h2>${esc(l.company)}</h2><div class=muted>${esc(l.contact_name||'Контакт не указан')} · ${esc(l.phone||'телефон не указан')}</div></div><div class=project-actions>${canConvert?'<button class="btn" id=convertLead>Продажа состоялась → в производство</button>':''}<button class="btn secondary" id=editLead>Изменить</button>${tag(l.stage)} ${tag(l.qualification,l.qualification==='qualified'?'ok':'')}</div></div><div class=lead-detail-grid><div class=stack><section class="card pad"><div class=card-head-inline><div><h3>Следующее действие</h3><p class=muted>Без следующего шага лид считается бесконтрольным</p></div><button class="btn small" id=addLeadActivity>+ Касание</button></div><div class="next-action ${l.next_action_due&&daysUntil(l.next_action_due)<0?'danger':''}"><strong>${esc(l.next_action||'Не задано')}</strong><span>${fmt(l.next_action_due)}</span></div></section><section class="card pad"><h3>Квалификация</h3><div class=info-list><p><span>Потребность</span><b>${esc(l.need||'—')}</b></p><p><span>Бюджет</span><b>${esc(l.budget||'—')}</b></p><p><span>Срок принятия решения</span><b>${esc(l.deadline||'—')}</b></p><p><span>ЛПР</span><b>${esc(l.decision_maker||'—')}</b></p><p><span>Причина отказа</span><b>${esc(l.loss_reason||'—')}</b></p></div></section><section class="card pad"><h3>История касаний</h3><div class=timeline>${x.activities.map(a=>`<div class=event><b>${esc(labels[a.type]||a.type)}</b><div>${esc(a.summary)}</div><small>${esc(a.user_name||'Система')} · ${fmt(a.occurred_at)}</small></div>`).join('')||'<div class=empty-compact>Касаний пока нет</div>'}</div></section></div><div class=stack><section class="card pad"><h3>Контакт и сделка</h3><div class=info-list><p><span>Телефон</span><b>${esc(l.phone||'—')}</b></p><p><span>Email</span><b>${esc(l.email||'—')}</b></p><p><span>Источник</span><b>${esc(l.source||'—')}</b></p><p><span>Услуга</span><b>${esc(l.service||'—')}</b></p><p><span>Ответственный</span><b>${esc(l.owner_name||'—')}</b></p><p><span>Последний контакт</span><b>${fmt(l.last_contact_at)}</b></p></div></section><section class="card pad"><h3>Заметки</h3><p class=project-summary>${esc(l.notes||'Нет заметок')}</p></section>${l.converted_project_id?`<section class="card pad"><h3>Проект создан</h3><button class="btn full" id=openConverted>Открыть в производстве</button></section>`:''}</div></div>`);$('#editLead').onclick=()=>leadModal(l);if($('#addLeadActivity'))$('#addLeadActivity').onclick=()=>leadActivityModal(l);if($('#convertLead'))$('#convertLead').onclick=()=>convertLeadModal(l);if($('#openConverted'))$('#openConverted').onclick=()=>navigate('project',l.converted_project_id)}
function renderProject(){const x=state.project,p=x.project;const tabs=[['overview','Обзор'],['success','Результат'],['calls','Созвоны'],['handoff','Передача'],['tasks','Задачи'],['launch','Запуск'],['reports','Отчёты'],['escalations','Эскалации'],['activity','Журнал']];const body=state.tab==='overview'?overview(x):state.tab==='success'?successView(x):state.tab==='calls'?calls(x):state.tab==='handoff'?handoff(x):state.tab==='tasks'?tasks(x):state.tab==='launch'?launch(x):state.tab==='reports'?reports(x):state.tab==='escalations'?escalations(x):activityView(x);shell(p.client,`<div class="project-header"><div><h2>${esc(p.client)}</h2><div class=muted>${esc(p.service)} · создан ${fmt(p.created_at)}</div></div><div class=project-actions>${p.stage==='lead'?'<button class="btn small" id=markSold>Продажа состоялась → передать Лизе</button>':''}${tag(p.stage)} ${tag(p.risk)}</div></div><div class=tabs>${tabs.map(([id,n])=>`<button data-tab="${id}" class="${state.tab===id?'active':''}">${n}</button>`).join('')}</div>${body}`);document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;renderProject()});bindProject();bindSuccess()}
function overview(x){const p=x.project,hDone=x.handoff.filter(i=>i.status==='accepted').length,lDone=x.launch.filter(i=>['done','na'].includes(i.status)).length,open=x.tasks.filter(t=>t.status!=='done'),hot=open.filter(taskHot).sort((a,b)=>(a.status==='blocked'?-1:0)-(b.status==='blocked'?-1:0)||(daysUntil(a.due_date)??9999)-(daysUntil(b.due_date)??9999)),events=[['Следующее действие',p.next_action_due,p.next_action||'Не задано'],['Дедлайн запуска',p.launch_deadline,'Контроль готовности к запуску'],['Контакт с клиентом',p.next_client_contact,'Следующая коммуникация'],['Недельный отчёт',p.next_report,'Подготовить и опубликовать отчёт']].filter(e=>e[1]),material=safeUrl(p.materials_url);return `<div class=project-kpis><div class="mini-stat ${hot.length?'danger':''}"><small>Горящие задачи</small><strong>${hot.length}</strong></div><div class=mini-stat><small>Открытые задачи</small><strong>${open.length}</strong></div><div class=mini-stat><small>Созвоны</small><strong>${x.calls.length}</strong></div><div class=mini-stat><small>Отчёты</small><strong>${x.reports.length}</strong></div></div><div class=workspace-grid><div class=stack><section class="card pad"><div class=card-head-inline><div><h3>Горящие и ближайшие задачи</h3><p class=muted>Блокировки, высокий приоритет и сроки в ближайшие два дня</p></div><button class="btn small" id=quickTask>+ Задача</button></div><div class=focus-list>${hot.slice(0,6).map(t=>`<div class="focus-task ${t.status==='blocked'||daysUntil(t.due_date)<0?'danger':''}"><div><strong>${esc(t.title)}</strong><small>${esc(t.assignee_name||'Не назначена')} · ${fmt(t.due_date)}</small></div><div>${t.status==='blocked'?tag('blocked'):tag(t.priority,t.priority==='urgent'?'danger':'warn')}</div></div>`).join('')||'<div class=empty-compact>Горящих задач нет. Можно спокойно работать по плану.</div>'}</div>${open.length?'<button class="btn secondary full" id=openTasks>Открыть все задачи</button>':''}</section><section class="card pad"><div class=card-head-inline><h3>Сводка проекта</h3><button class="btn secondary small" id=editProject>Изменить</button></div><p class=project-summary>${esc(p.call_summary||'Сводка ещё не добавлена.')}</p>${material?`<a class=source-link href="${esc(material)}" target=_blank rel="noopener">Открыть исходные материалы ↗</a>`:''}</section><section class="card pad"><h3>Последние изменения</h3><div class=mini-timeline>${x.activity.slice(0,5).map(a=>`<div><span></span><p><b>${esc(a.action)}</b><br><small>${esc(a.details||'')} · ${fmt(a.created_at)}</small></p></div>`).join('')||'<div class=muted>История пока пуста</div>'}</div></section></div><div class=stack><section class="card pad"><h3>Сроки и контроль</h3><div class=deadline-list>${events.map(([name,date,note])=>{const left=daysUntil(date),cls=left<0?'danger':left<=2?'warn':'';return `<div class="deadline ${cls}"><div><b>${name}</b><small>${esc(note)}</small></div><strong>${fmt(date)}${left<0?` · просрочено ${Math.abs(left)} дн.`:left===0?' · сегодня':left!==null?` · через ${left} дн.`:''}</strong></div>`}).join('')||'<div class=empty-compact>Ключевые сроки ещё не заданы</div>'}</div></section><section class="card pad"><h3>Готовность проекта</h3><p class=muted>Передача — ${hDone}/${x.handoff.length}</p><div class=progress><i style="width:${x.handoff.length?100*hDone/x.handoff.length:0}%"></i></div><p class=muted>Запуск — ${lDone}/${x.launch.length}</p><div class=progress><i style="width:${x.launch.length?100*lDone/x.launch.length:0}%"></i></div></section><section class="card pad"><h3>Ответственные и риски</h3><div class=info-list><p><span>Менеджер</span><b>${esc(p.manager_name||'Не назначен')}</b></p><p><span>Этап</span>${tag(p.stage)}</p><p><span>Риск</span>${tag(p.risk)}</p><p><span>Эскалации</span><b>${x.escalations.filter(e=>e.status==='open').length}</b></p></div></section><section class="card pad"><h3>Клиентская отчётность</h3><p class=muted>Публичная ссылка показывает только опубликованные недельные отчёты.</p><button class="btn secondary full" id=copyReport>Скопировать ссылку</button></section></div></div>`}
function successView(x){const s=x.success_profile,a=x.daily_audits||[],latest=a[0],actions=x.optimization_actions||[],rub=v=>v===null||v===undefined?'—':`${Number(v).toLocaleString('ru-RU',{maximumFractionDigits:2})} ₽`,num=v=>v===null||v===undefined?'—':Number(v).toLocaleString('ru-RU',{maximumFractionDigits:2});return `<div class="gate ${s?'open':'closed'}">${s?'Паспорт результата заполнен — проект можно вести по измеримым KPI':'До запуска заполните паспорт результата: цель, KPI, бюджет, аналитика, оффер и структура кампаний'}</div><div class=project-kpis><div class=mini-stat><small>Последний аудит</small><strong>${latest?fmt(latest.audit_date):'—'}</strong></div><div class="mini-stat ${latest&&['attention','critical','unavailable'].includes(latest.status)?'danger':''}"><small>Статус</small><strong>${latest?esc(labels[latest.status]||latest.status):'—'}</strong></div><div class=mini-stat><small>Конверсии</small><strong>${latest?num(latest.conversions):'—'}</strong></div><div class=mini-stat><small>CPA / CPL</small><strong>${latest?rub(latest.cpa):'—'}</strong></div></div><div class=workspace-grid><div class=stack><section class="card pad"><div class=card-head-inline><div><h3>Паспорт результата</h3><p class=muted>Единые вводные вместо настройки по свободному голосовому сообщению</p></div><button class="btn small" id=editSuccess>${s?'Изменить':'Заполнить'}</button></div>${s?`<div class=info-list><p><span>Бизнес-цель</span><b>${esc(s.business_goal)}</b></p><p><span>Главный KPI</span><b>${esc(s.primary_kpi.toUpperCase())}: ${esc(s.target_value)}</b></p><p><span>Бюджет в месяц</span><b>${esc(s.monthly_budget)}</b></p><p><span>Direct / Метрика</span><b>${esc(s.direct_login)} / ${esc(s.metrika_counter_id)}</b></p><p><span>География</span><b>${esc(s.geo)}</b></p><p><span>Оффер</span><b>${esc(s.offer)}</b></p><p><span>Аудитория</span><b>${esc(s.audience)}</b></p><p><span>Структура кампаний</span><b>${esc(s.campaign_blueprint)}</b></p><p><span>Автокорректировки</span><b>${s.auto_actions_enabled?'Разрешены в безопасных пределах':'Только после проверки'}</b></p></div>`:'<div class=empty-compact>Паспорт ещё не заполнен. Запуск кампаний будет заблокирован.</div>'}</section><section class="card"><div class=card-head><div><h3>Ежедневный контроль</h3><p class=muted>Факт → отклонение → принятое действие</p></div><button class="btn small" id=newDailyAudit>+ Аудит</button></div><div class=table-wrap><table class=table><thead><tr><th>Дата</th><th>Данные</th><th>Статус</th><th>Показы</th><th>Клики</th><th>Расход</th><th>Конверсии</th><th>CPA</th></tr></thead><tbody>${a.map(d=>`<tr><td>${esc(d.audit_date)}</td><td>${tag(d.source_status,d.source_status==='unavailable'?'danger':'ok')}</td><td>${tag(d.status,['critical','unavailable'].includes(d.status)?'danger':d.status==='attention'?'warn':'ok')}</td><td>${num(d.impressions)}</td><td>${num(d.clicks)}</td><td>${rub(d.spend)}</td><td>${num(d.conversions)}</td><td>${rub(d.cpa)}</td></tr><tr class=audit-detail><td colspan=8><b>Вывод:</b> ${esc(d.findings||'—')}<br><b>Действия:</b> ${esc(d.actions||'—')}</td></tr>`).join('')||'<tr><td colspan=8 class=empty>Аудитов пока нет</td></tr>'}</tbody></table></div></section></div><div class=stack><section class="card pad"><div class=card-head-inline><div><h3>Журнал корректировок</h3><p class=muted>Каждое изменение с основанием и состоянием до/после</p></div><button class="btn small" id=newOptimization>+ Действие</button></div><div class=action-log>${actions.map(o=>`<article class=action-item><div>${tag(o.status,o.status==='applied'?'ok':o.status==='approval_required'?'warn':'')} <b>${esc(o.action)}</b></div><small>${esc(o.action_date)} · ${esc(o.category)} · ${esc(o.entity||'весь проект')}</small><p>${esc(o.rationale)}</p>${o.before_value||o.after_value?`<div class=before-after><span>${esc(o.before_value||'—')}</span><b>→</b><span>${esc(o.after_value||'—')}</span></div>`:''}</article>`).join('')||'<div class=empty-compact>Корректировки ещё не зафиксированы</div>'}</div></section>${s?`<section class="card pad"><h3>Аналитика и ограничения</h3><div class=info-list><p><span>CRM / источник лидов</span><b>${esc(s.crm_source)}</b></p><p><span>Посадочная</span><b>${esc(s.landing_url)}</b></p><p><span>Ограничения</span><b>${esc(s.restrictions)}</b></p></div></section>`:''}</div></div>`}
function calls(x){return `<div class=toolbar><div><h2>История созвонов</h2><div class=muted>Новый Plaud-коннектор позже будет писать сюда автоматически</div></div><button class=btn id=newProjectCall>+ Добавить созвон</button></div><section class=card>${x.calls.map(c=>`<article class=report><small>${fmt(c.occurred_at||c.created_at)} · ${esc(c.source)} · ${esc(c.author_name||'Интеграция')}</small><h3>${esc(c.title||'Созвон')}</h3>${c.summary?`<div><label>Сводка</label><p>${esc(c.summary)}</p></div>`:''}${c.transcript?`<details><summary>Расшифровка</summary><p>${esc(c.transcript)}</p></details>`:''}</article>`).join('')||'<div class=empty>Созвонов пока нет</div>'}</section>`}
function handoff(x){const open=x.handoff.filter(i=>i.status!=='accepted').length;return `<div class="gate ${open?'closed':'open'}">${open?`Передача не принята: осталось ${open} обязательных пунктов`:'Все вводные подтверждены — проект можно принять'}</div><section class=card><div class=card-head><h3>Пакет передачи</h3><button class=btn id=acceptHandoff ${open?'disabled':''}>Принять проект</button></div><div class=checklist>${x.handoff.map(i=>`<div class=check data-hi="${i.id}"><div><div class=section>${esc(i.section)}</div><h4>${esc(i.label)}</h4><p>${esc(i.hint)}</p></div><input class=value value="${esc(i.value)}" placeholder="Значение / договорённость"><select class=status><option value=missing ${i.status==='missing'?'selected':''}>Не заполнено</option><option value=filled ${i.status==='filled'?'selected':''}>Заполнено</option><option value=clarify ${i.status==='clarify'?'selected':''}>Уточнить</option><option value=accepted ${i.status==='accepted'?'selected':''}>Принято</option></select><input class=proof value="${esc(i.proof)}" placeholder="Доказательство или ссылка"><button class="btn small save">✓</button></div>`).join('')}</div></section>`}
function launch(x){const open=x.launch.filter(i=>!['done','na'].includes(i.status)).length;return `<div class="gate ${open?'closed':'open'}">${open?`ЗАПУСК ЗАПРЕЩЁН — незакрытых проверок: ${open}`:'МОЖНО ЗАПУСКАТЬ — все проверки подтверждены'}</div>${!open?'<button class="btn" id=markLaunched>Перевести в «Запущен»</button><br><br>':''}<section class=card><div class=checklist>${x.launch.map(i=>`<div class=check data-li="${i.id}"><div><div class=section>${esc(i.stage)} · ${esc(i.assignee)}</div><h4>${esc(i.label)}</h4><p>${esc(i.criterion)}</p></div><input type=date class=due value="${esc(i.due_date||'')}"><select class=status><option value=todo ${i.status==='todo'?'selected':''}>Не начато</option><option value=doing ${i.status==='doing'?'selected':''}>В работе</option><option value=done ${i.status==='done'?'selected':''}>Готово</option><option value=stop ${i.status==='stop'?'selected':''}>СТОП</option><option value=na ${i.status==='na'?'selected':''}>Не применимо</option></select><input class=proof value="${esc(i.proof)}" placeholder="Ссылка, ID, дата или цифра"><button class="btn small save">✓</button></div>`).join('')}</div></section>`}
function tasks(x){const cols=[['blocked','Блок'],['backlog','План'],['doing','В работе'],['review_task','Проверка'],['done','Готово']],open=x.tasks.filter(t=>t.status!=='done'),overdue=open.filter(t=>daysUntil(t.due_date)<0).length,hot=open.filter(taskHot).length;return `<div class=task-strip><span>${tag(`${open.length} открыто`,'accent')}</span><span>${tag(`${hot} горит`,hot?'warn':'ok')}</span><span>${tag(`${overdue} просрочено`,overdue?'danger':'ok')}</span><button class=btn id=newTask>+ Задача</button></div><div class=kanban>${cols.map(([s,n])=>`<section class="column column-${s}"><div class=column-head>${n}<span>${x.tasks.filter(t=>t.status===s).length}</span></div>${x.tasks.filter(t=>t.status===s).map(t=>{const left=daysUntil(t.due_date),late=left!==null&&left<0,next=s==='blocked'?'doing':s==='backlog'?'doing':s==='doing'?'review_task':s==='review_task'?'done':'';return `<article class="task priority-${t.priority} ${late?'task-overdue':''}"><div class=task-labels>${late?tag('Просрочено','danger'):''}${t.priority!=='normal'?tag(t.priority,t.priority==='urgent'?'danger':'warn'):''}</div><strong>${esc(t.title)}</strong>${t.description?`<div class=task-desc>${esc(t.description)}</div>`:''}<small>${esc(t.assignee_name||'Не назначена')} · ${fmt(t.due_date)}</small><div class=task-actions>${next?`<button class="btn small" data-task="${t.id}" data-status="${next}">${s==='blocked'?'Разблокировать':'→'}</button>`:''}<button class="btn secondary small" data-edit-task="${t.id}">Изменить</button>${!['blocked','done'].includes(s)?`<button class="btn secondary small" data-block="${t.id}">Блок</button>`:''}</div></article>`}).join('')||'<div class=column-empty>Нет задач</div>'}</section>`).join('')}</div>`}
function reports(x){return `<div class=toolbar><div class=muted>Подтверждённые цифры, отклонения и следующее действие</div><button class=btn id=newReport>+ Недельный отчёт</button></div><section class=card>${x.reports.map(r=>`<article class=report><small>${esc(r.period)} · ${fmt(r.created_at)} · ${esc(r.author_name)}</small><h3>${tag(r.risk)} Результат недели</h3><div class=report-grid><div><label>Что сделано</label><p>${esc(r.completed)}</p></div><div><label>Подтверждённые цифры</label><p>${esc(r.metrics)}</p></div><div><label>Отклонение / причина</label><p>${esc(r.deviation||'Нет')} ${esc(r.reason)}</p></div><div><label>Следующие шаги</label><p>${esc(r.next_steps)}</p></div></div>${r.client_message?`<div class=gate style="background:#f0efff">${esc(r.client_message)}</div>`:''}</article>`).join('')||'<div class=empty>Отчётов пока нет</div>'}</section>`}
function escalations(x){return `<div class=toolbar><div class=muted>Факты → влияние → два варианта → рекомендация</div><button class=btn id=newEscalation>+ Эскалация</button></div><section class=card>${x.escalations.map(e=>`<article class=escalation><div>${tag(e.status)} <b>${esc(e.type)}</b> · ${fmt(e.created_at)}</div><p><b>Факты:</b> ${esc(e.facts)}</p><p><b>Влияние:</b> ${esc(e.impact)}</p><p><b>Вариант A:</b> ${esc(e.option_a)}</p><p><b>Вариант B:</b> ${esc(e.option_b)}</p><p><b>Рекомендация:</b> ${esc(e.recommendation)}</p>${e.status==='open'?`<button class="btn secondary small" data-resolve="${e.id}">Закрыть</button>`:''}</article>`).join('')||'<div class=empty>Открытых эскалаций нет</div>'}</section>`}
function activityView(x){return `<section class=card><div class=card-head><h3>История изменений</h3></div><div class=timeline>${x.activity.map(a=>`<div class=event><b>${esc(a.action)}</b><div>${esc(a.details)}</div><small>${esc(a.user_name||'Система')} · ${fmt(a.created_at)}</small></div>`).join('')}</div></section>`}
function bindProject(){const x=state.project,p=x.project;if($('#editProject'))$('#editProject').onclick=()=>projectModal(p);if($('#quickTask'))$('#quickTask').onclick=()=>taskModal();if($('#openTasks'))$('#openTasks').onclick=()=>{state.tab='tasks';renderProject()};if($('#newProjectCall'))$('#newProjectCall').onclick=()=>projectCallModal(p);if($('#markSold'))$('#markSold').onclick=async()=>{await api(`api/projects/${p.id}`,{method:'PATCH',body:JSON.stringify({stage:'handoff',sale_date:new Date().toISOString().slice(0,10),next_action:'Лизе проверить сводку и принять передачу'})});await reloadProject('Продажа зафиксирована — проект передан Лизе')};if($('#copyReport'))$('#copyReport').onclick=()=>{navigator.clipboard.writeText(`${location.origin}${location.pathname.replace(/\/$/,'')}/report/${p.public_token}`);toast('Ссылка на клиентский отчёт скопирована')};document.querySelectorAll('[data-hi] .save').forEach(b=>b.onclick=async()=>{const r=b.closest('[data-hi]');try{await api(`api/projects/${p.id}/handoff/${r.dataset.hi}`,{method:'PATCH',body:JSON.stringify({value:r.querySelector('.value').value,status:r.querySelector('.status').value,proof:r.querySelector('.proof').value})});await reloadProject('Пункт передачи сохранён')}catch(e){toast(e.message,true)}});if($('#acceptHandoff'))$('#acceptHandoff').onclick=async()=>{try{await api(`api/projects/${p.id}`,{method:'PATCH',body:JSON.stringify({acceptance_status:'accepted',handoff_date:new Date().toISOString().slice(0,10),stage:'preparing'})});await reloadProject('Проект принят Лизой')}catch(e){toast(e.message,true)}};document.querySelectorAll('[data-li] .save').forEach(b=>b.onclick=async()=>{const r=b.closest('[data-li]');try{await api(`api/projects/${p.id}/launch/${r.dataset.li}`,{method:'PATCH',body:JSON.stringify({status:r.querySelector('.status').value,due_date:r.querySelector('.due').value,proof:r.querySelector('.proof').value})});await reloadProject('Проверка сохранена')}catch(e){toast(e.message,true)}});if($('#markLaunched'))$('#markLaunched').onclick=async()=>{try{await api(`api/projects/${p.id}`,{method:'PATCH',body:JSON.stringify({stage:'launched'})});await reloadProject('Проект переведён в запуск')}catch(e){toast(e.message,true)}};if($('#newTask'))$('#newTask').onclick=()=>taskModal();document.querySelectorAll('[data-task]').forEach(b=>b.onclick=async()=>{await api(`api/tasks/${b.dataset.task}`,{method:'PATCH',body:JSON.stringify({status:b.dataset.status})});await reloadProject('Статус задачи изменён')});document.querySelectorAll('[data-edit-task]').forEach(b=>b.onclick=()=>taskModal(x.tasks.find(t=>String(t.id)===b.dataset.editTask)));document.querySelectorAll('[data-block]').forEach(b=>b.onclick=async()=>{await api(`api/tasks/${b.dataset.block}`,{method:'PATCH',body:JSON.stringify({status:'blocked'})});await reloadProject('Задача заблокирована')});if($('#newReport'))$('#newReport').onclick=()=>reportModal();if($('#newEscalation'))$('#newEscalation').onclick=()=>escalationModal();document.querySelectorAll('[data-resolve]').forEach(b=>b.onclick=async()=>{await api(`api/escalations/${b.dataset.resolve}`,{method:'PATCH',body:JSON.stringify({status:'resolved'})});await reloadProject('Эскалация закрыта')})}
function bindSuccess(){if($('#editSuccess'))$('#editSuccess').onclick=()=>successProfileModal(state.project.success_profile);if($('#newDailyAudit'))$('#newDailyAudit').onclick=()=>dailyAuditModal();if($('#newOptimization'))$('#newOptimization').onclick=()=>optimizationModal()}
async function reloadProject(msg){state.project=await api(`api/projects/${state.project.project.id}/all`);renderProject();if(msg)toast(msg)}
function modal(title,html,onSubmit){const n=document.createElement('div');n.className='modal-back';n.innerHTML=`<div class=modal><div class=modal-head><h2>${title}</h2><button class=close>×</button></div><form class=modal-body>${html}<div class=modal-actions><button type=button class="btn secondary cancel">Отмена</button><button class=btn>Сохранить</button></div></form></div>`;document.body.append(n);n.querySelector('.close').onclick=n.querySelector('.cancel').onclick=()=>n.remove();n.onclick=e=>{if(e.target===n)n.remove()};n.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await onSubmit(formData(e.target));n.remove()}catch(x){toast(x.message,true)}};return n}
function projectModal(p=null){const options=state.users.filter(u=>u.role!=='owner').map(u=>`<option value="${u.id}" ${Number(p?.manager_id)===u.id?'selected':''}>${esc(u.name)}</option>`).join(''),stages=['lead','sold','handoff','preparing','review','ready','launched','management','paused','completed'];modal(p?'Карточка проекта':'Новый проект',`<div class=form-grid><div class=field><label>Клиент *</label><input name=client required value="${esc(p?.client||'')}"></div><div class=field><label>Услуга *</label><input name=service required value="${esc(p?.service||'')}"></div><div class=field><label>Этап</label><select name=stage>${stages.map(v=>`<option value=${v} ${p?.stage===v?'selected':''}>${labels[v]}</option>`)}</select></div><div class=field><label>Менеджер</label><select name=manager_id><option value="">Не назначен</option>${options}</select></div><div class=field><label>Дата продажи</label><input type=date name=sale_date value="${esc(p?.sale_date||new Date().toISOString().slice(0,10))}"></div><div class=field><label>Дедлайн запуска</label><input type=date name=launch_deadline value="${esc(p?.launch_deadline||'')}"></div><div class=field><label>Риск</label><select name=risk>${['none','low','medium','high','stop'].map(v=>`<option value=${v} ${p?.risk===v?'selected':''}>${labels[v]}</option>`)}</select></div><div class=field><label>Контакт с клиентом</label><input type=date name=next_client_contact value="${esc(p?.next_client_contact||'')}"></div><div class="field span-2"><label>Следующее действие</label><input name=next_action value="${esc(p?.next_action||'')}"></div><div class=field><label>Срок действия</label><input type=date name=next_action_due value="${esc(p?.next_action_due||'')}"></div><div class=field><label>Следующий отчёт</label><input type=date name=next_report value="${esc(p?.next_report||'')}"></div><div class="field span-2"><label>Сводка созвона / проекта</label><textarea name=call_summary>${esc(p?.call_summary||'')}</textarea></div><div class="field span-2"><label>Ссылка на материалы</label><input name=materials_url value="${esc(p?.materials_url||'')}"></div></div>`,async x=>{if(p){await api(`api/projects/${p.id}`,{method:'PATCH',body:JSON.stringify(x)});await reloadProject('Карточка проекта обновлена')}else{const r=await api('api/projects',{method:'POST',body:JSON.stringify(x)});toast('Проект создан');await navigate('project',r.id)}})}
function leadModal(l=null){const stages=['new','contacted','qualified','meeting','proposal','won','lost'],quals=['unqualified','qualified','bad_fit'];modal(l?'Карточка лида':'Новый лид',`<div class=form-grid><div class=field><label>Компания / имя *</label><input name=company required value="${esc(l?.company||'')}"></div><div class=field><label>Контактное лицо</label><input name=contact_name value="${esc(l?.contact_name||'')}"></div><div class=field><label>Телефон</label><input name=phone value="${esc(l?.phone||'')}"></div><div class=field><label>Email</label><input type=email name=email value="${esc(l?.email||'')}"></div><div class=field><label>Источник</label><input name=source value="${esc(l?.source||'')}"></div><div class=field><label>Услуга</label><input name=service value="${esc(l?.service||'')}"></div><div class=field><label>Этап</label><select name=stage>${stages.map(v=>`<option value=${v} ${l?.stage===v?'selected':''}>${labels[v]}</option>`)}</select></div><div class=field><label>Квалификация</label><select name=qualification>${quals.map(v=>`<option value=${v} ${l?.qualification===v?'selected':''}>${labels[v]}</option>`)}</select></div><div class=field><label>Бюджет</label><input name=budget value="${esc(l?.budget||'')}"></div><div class=field><label>Срок принятия решения</label><input name=deadline value="${esc(l?.deadline||'')}"></div><div class="field span-2"><label>Потребность / задача клиента</label><textarea name=need>${esc(l?.need||'')}</textarea></div><div class=field><label>ЛПР</label><input name=decision_maker value="${esc(l?.decision_maker||'')}"></div><div class=field><label>Ответственный</label><select name=owner_id><option value="${state.me.id}">${esc(state.me.name)}</option>${state.users.filter(u=>u.role==='owner'&&u.id!==state.me.id).map(u=>`<option value=${u.id} ${Number(l?.owner_id)===u.id?'selected':''}>${esc(u.name)}</option>`).join('')}</select></div><div class="field span-2"><label>Следующее действие *</label><input name=next_action value="${esc(l?.next_action||'')}"></div><div class=field><label>Срок следующего действия</label><input type=date name=next_action_due value="${esc(l?.next_action_due||'')}"></div><div class=field><label>Последний контакт</label><input type=datetime-local name=last_contact_at value="${esc(String(l?.last_contact_at||'').replace(' ','T').slice(0,16))}"></div><div class="field span-2"><label>Причина проигрыша</label><input name=loss_reason value="${esc(l?.loss_reason||'')}"></div><div class="field span-2"><label>Заметки</label><textarea name=notes>${esc(l?.notes||'')}</textarea></div></div>`,async x=>{if(l){await api(`api/leads/${l.id}`,{method:'PATCH',body:JSON.stringify(x)});state.lead=await api(`api/leads/${l.id}`);renderLead();toast('Лид обновлён')}else{const r=await api('api/leads',{method:'POST',body:JSON.stringify(x)});await navigate('lead',r.id);toast('Лид создан')}})}
function leadActivityModal(l){modal('Новое касание',`<div class=form-grid><div class=field><label>Тип</label><select name=type><option value=call>Звонок</option><option value=message>Сообщение</option><option value=meeting>Созвон / встреча</option><option value=note>Заметка</option></select></div><div class=field><label>Дата и время</label><input type=datetime-local name=occurred_at></div><div class="field span-2"><label>Результат *</label><textarea name=summary required placeholder="Что обсудили, результат и договорённость"></textarea></div></div>`,async x=>{await api(`api/leads/${l.id}/activities`,{method:'POST',body:JSON.stringify(x)});state.lead=await api(`api/leads/${l.id}`);renderLead();toast('Касание добавлено')})}
function convertLeadModal(l){const options=state.users.filter(u=>u.role==='manager').map(u=>`<option value=${u.id}>${esc(u.name)}</option>`).join('');modal('Передать в производство',`<p class=muted>Будет создан отдельный проект с обязательной передачей и воротами запуска.</p><div class=field><label>Проджект</label><select name=manager_id><option value="">Не назначен</option>${options}</select></div><div class=field><label>Дедлайн запуска</label><input type=date name=launch_deadline></div>`,async x=>{const r=await api(`api/leads/${l.id}/convert`,{method:'POST',body:JSON.stringify(x)});toast('Продажа зафиксирована, проект создан');await navigate('project',r.project_id)})}
function callIntakeModal(){modal('Новый созвон',`<p class=muted>Новый контакт попадёт в «Продажи». Если клиент уже находится в производстве, созвон добавится в его проект.</p><div class=form-grid><div class=field><label>Название клиента — необязательно</label><input name=project_name placeholder="Можно указать в финальной фразе"></div><div class=field><label>Дата созвона</label><input type=datetime-local name=occurred_at></div><div class="field span-2"><label>Название созвона</label><input name=title placeholder="Первичный созвон"></div><div class="field span-2"><label>Сводка</label><textarea name=summary placeholder="Краткие договорённости, цели и следующие шаги"></textarea></div><div class="field span-2"><label>Расшифровка</label><textarea name=transcript placeholder="...\nПроект Мария"></textarea></div><input type=hidden name=source value=manual></div>`,async x=>{const r=await api('api/calls/intake',{method:'POST',body:JSON.stringify(x)});if(r.kind==='lead'){toast(r.lead_created?'Создан новый лид':'Созвон добавлен в лид');await navigate('lead',r.lead_id)}else{toast('Созвон добавлен в существующий проект');state.tab='calls';await navigate('project',r.project_id)}})}
function projectCallModal(p){modal(`Созвон: ${esc(p.client)}`,`<div class=form-grid><div class=field><label>Дата созвона</label><input type=datetime-local name=occurred_at></div><div class=field><label>Источник</label><select name=source><option value=manual>Вручную</option><option value=plaud>Plaud</option><option value=telegram>Telegram</option></select></div><div class="field span-2"><label>Название</label><input name=title placeholder="Повторный созвон"></div><div class="field span-2"><label>Сводка</label><textarea name=summary></textarea></div><div class="field span-2"><label>Расшифровка</label><textarea name=transcript></textarea></div></div>`,async x=>{await api(`api/projects/${p.id}/calls`,{method:'POST',body:JSON.stringify(x)});await reloadProject('Созвон добавлен в историю')})}
function taskModal(t=null){modal(t?'Изменить задачу':'Новая задача',`<div class=field><label>Задача *</label><input name=title required value="${esc(t?.title||'')}"></div><div class=field><label>Описание</label><textarea name=description>${esc(t?.description||'')}</textarea></div><div class=form-grid><div class=field><label>Исполнитель</label><select name=assignee_id><option value="">Не назначен</option>${state.users.map(u=>`<option value=${u.id} ${Number(t?.assignee_id)===u.id?'selected':''}>${esc(u.name)}</option>`).join('')}</select></div><div class=field><label>Срок</label><input type=date name=due_date value="${esc(t?.due_date||'')}"></div><div class=field><label>Приоритет</label><select name=priority>${['normal','high','urgent'].map(v=>`<option value=${v} ${t?.priority===v?'selected':''}>${v==='normal'?'Обычный':v==='high'?'Высокий':'Срочный'}</option>`)}</select></div><div class=field><label>Статус</label><select name=status>${['backlog','doing','review_task','blocked','done'].map(v=>`<option value=${v} ${t?.status===v?'selected':''}>${labels[v]}</option>`)}</select></div><div class="field span-2"><label>Результат / доказательство</label><input name=proof value="${esc(t?.proof||'')}"></div></div>`,async x=>{if(t)await api(`api/tasks/${t.id}`,{method:'PATCH',body:JSON.stringify(x)});else await api(`api/projects/${state.project.project.id}/tasks`,{method:'POST',body:JSON.stringify(x)});await reloadProject(t?'Задача обновлена':'Задача создана')})}
function reportModal(){modal('Недельный отчёт',`<div class=form-grid><div class=field><label>Период *</label><input name=period placeholder="26.10–01.11" required></div><div class=field><label>Следующий отчёт</label><input type=date name=next_report></div><div class="field span-2"><label>Что планировали *</label><textarea name=planned required></textarea></div><div class="field span-2"><label>Что сделано *</label><textarea name=completed required></textarea></div><div class="field span-2"><label>Подтверждённые цифры *</label><textarea name=metrics placeholder="Расход — …; лиды — …; CPL — …" required></textarea></div><div class=field><label>Отклонение</label><textarea name=deviation></textarea></div><div class=field><label>Причина</label><textarea name=reason></textarea></div><div class="field span-2"><label>Следующие шаги *</label><textarea name=next_steps required></textarea></div><div class=field><label>Риск</label><select name=risk>${['none','low','medium','high','stop'].map(v=>`<option value=${v}>${labels[v]}</option>`)}</select></div><div class="field span-2"><label>Сообщение клиенту</label><textarea name=client_message></textarea></div></div>`,async x=>{await api(`api/projects/${state.project.project.id}/reports`,{method:'POST',body:JSON.stringify(x)});await reloadProject('Отчёт опубликован')})}
function escalationModal(){modal('Новая эскалация',`<div class=field><label>Тип ситуации *</label><select name=type><option>Не хватает вводных</option><option>Риск срыва запуска</option><option>Ошибка в настройке или отчёте</option><option>Недовольство клиента</option><option>Изменение бюджета или договора</option></select></div><div class=field><label>Факты *</label><textarea name=facts required></textarea></div><div class=field><label>Влияние на срок, деньги или клиента *</label><textarea name=impact required></textarea></div><div class=form-grid><div class=field><label>Вариант A *</label><textarea name=option_a required></textarea></div><div class=field><label>Вариант B *</label><textarea name=option_b required></textarea></div><div class="field span-2"><label>Рекомендация Лизы *</label><textarea name=recommendation required></textarea></div></div>`,async x=>{await api(`api/projects/${state.project.project.id}/escalations`,{method:'POST',body:JSON.stringify(x)});await reloadProject('Эскалация создана')})}
function renderAccount(){shell('Профиль',`<div class=summary-grid><section class="card pad"><h2>${esc(state.me.name)}</h2><p class=muted>Логин: ${esc(state.me.login)}</p><p>Роль: ${esc(state.me.role)}</p></section><section class="card pad"><h3>Сменить пароль</h3><form id=pass><div class=field><label>Новый пароль</label><input type=password name=password minlength=10 required></div><button class=btn>Обновить</button></form></section></div>`);$('#pass').onsubmit=async e=>{e.preventDefault();try{await api('api/change-password',{method:'POST',body:JSON.stringify(formData(e.target))});e.target.reset();toast('Пароль изменён')}catch(x){toast(x.message,true)}}}
function successProfileModal(s={}){modal('Паспорт результата',`<p class=muted>Все поля обязательны. Без готового паспорта система не разрешит перевод проекта в запуск.</p><div class=form-grid><div class="field span-2"><label>Бизнес-цель *</label><input name=business_goal required value="${esc(s?.business_goal||'')}" placeholder="Например: 60 квалифицированных заявок в месяц"></div><div class=field><label>Главный KPI *</label><select name=primary_kpi><option value=cpl ${s?.primary_kpi==='cpl'?'selected':''}>CPL / цена лида</option><option value=cpa ${s?.primary_kpi==='cpa'?'selected':''}>CPA / цена продажи</option><option value=leads ${s?.primary_kpi==='leads'?'selected':''}>Количество лидов</option><option value=romi ${s?.primary_kpi==='romi'?'selected':''}>ROMI</option><option value=drr ${s?.primary_kpi==='drr'?'selected':''}>ДРР</option></select></div><div class=field><label>Целевое значение *</label><input name=target_value required value="${esc(s?.target_value||'')}"></div><div class=field><label>Месячный бюджет *</label><input name=monthly_budget required value="${esc(s?.monthly_budget||'')}"></div><div class=field><label>Логин клиента Direct *</label><input name=direct_login required value="${esc(s?.direct_login||'')}"></div><div class=field><label>ID счётчика Метрики *</label><input name=metrika_counter_id required value="${esc(s?.metrika_counter_id||'')}"></div><div class=field><label>CRM / источник фактических лидов *</label><input name=crm_source required value="${esc(s?.crm_source||'')}"></div><div class="field span-2"><label>Посадочная страница *</label><input type=url name=landing_url required value="${esc(s?.landing_url||'')}"></div><div class=field><label>География *</label><input name=geo required value="${esc(s?.geo||'')}"></div><div class=field><label>Оффер *</label><input name=offer required value="${esc(s?.offer||'')}"></div><div class="field span-2"><label>Целевая аудитория *</label><textarea name=audience required>${esc(s?.audience||'')}</textarea></div><div class="field span-2"><label>Ограничения и запрещённые обещания *</label><textarea name=restrictions required>${esc(s?.restrictions||'')}</textarea></div><div class="field span-2"><label>Утверждённая структура кампаний *</label><textarea name=campaign_blueprint required placeholder="Поиск: горячие / конкурентные / бренд; РСЯ; ретаргетинг; исключения">${esc(s?.campaign_blueprint||'')}</textarea></div><div class=field><label>Автокорректировки</label><select name=auto_actions_enabled><option value=0 ${!s?.auto_actions_enabled?'selected':''}>Только после проверки</option><option value=1 ${s?.auto_actions_enabled?'selected':''}>Разрешить безопасные действия</option></select></div></div>`,async x=>{await api(`api/projects/${state.project.project.id}/success-profile`,{method:'PUT',body:JSON.stringify(x)});await reloadProject('Паспорт результата сохранён')})}
function dailyAuditModal(){const today=new Date(Date.now()-86400000).toISOString().slice(0,10);modal('Ежедневный аудит',`<div class=form-grid><div class=field><label>Дата данных *</label><input type=date name=audit_date required value="${today}"></div><div class=field><label>Подтверждённость *</label><select name=source_status><option value=confirmed>Данные подтверждены</option><option value=confirmed_zero>Подтверждённый ноль</option><option value=unavailable>Источник недоступен</option></select></div><div class=field><label>Итог *</label><select name=status><option value=ok>Норма</option><option value=attention>Требует внимания</option><option value=critical>Критично</option><option value=unavailable>Нет данных</option></select></div><div></div><div class=field><label>Показы</label><input type=number min=0 name=impressions></div><div class=field><label>Клики</label><input type=number min=0 name=clicks></div><div class=field><label>Расход</label><input type=number min=0 step=.01 name=spend></div><div class=field><label>Конверсии</label><input type=number min=0 step=.01 name=conversions></div><div class=field><label>CPA / CPL</label><input type=number min=0 step=.01 name=cpa></div><div class="field span-2"><label>Выводы</label><textarea name=findings placeholder="Что отклонилось от цели и почему"></textarea></div><div class="field span-2"><label>Принятые действия</label><textarea name=actions placeholder="Что изменено или поставлено на согласование"></textarea></div><div class="field span-2"><label>Ссылка / ID источника</label><input name=raw_reference></div></div>`,async x=>{await api(`api/projects/${state.project.project.id}/daily-audits`,{method:'POST',body:JSON.stringify(x)});await reloadProject('Ежедневный аудит сохранён')})}
function optimizationModal(){const today=new Date().toISOString().slice(0,10);modal('Корректировка кампании',`<div class=form-grid><div class=field><label>Дата *</label><input type=date name=action_date required value="${today}"></div><div class=field><label>Категория</label><select name=category><option value=search_terms>Поисковые запросы</option><option value=bids>Ставки и стратегия</option><option value=budget>Бюджет</option><option value=ads>Объявления</option><option value=targeting>Таргетинг</option><option value=analytics>Аналитика</option><option value=landing>Посадочная</option></select></div><div class="field span-2"><label>Объект изменения</label><input name=entity placeholder="Кампания, группа, фраза или цель"></div><div class="field span-2"><label>Действие *</label><input name=action required></div><div class="field span-2"><label>Основание *</label><textarea name=rationale required placeholder="Подтверждённые данные, на которых основано решение"></textarea></div><div class=field><label>Риск</label><select name=risk_level><option value=low>Низкий</option><option value=medium>Средний</option><option value=high>Высокий</option></select></div><div class=field><label>Статус</label><select name=status><option value=planned>Запланировано</option><option value=approval_required>Нужно согласование</option><option value=applied>Выполнено</option><option value=rejected>Отклонено</option><option value=rolled_back>Отменено</option></select></div><div class=field><label>До</label><textarea name=before_value></textarea></div><div class=field><label>После</label><textarea name=after_value></textarea></div><div class="field span-2"><label>Доказательство / ссылка</label><input name=proof></div></div>`,async x=>{await api(`api/projects/${state.project.project.id}/optimization-actions`,{method:'POST',body:JSON.stringify(x)});await reloadProject('Корректировка записана в журнал')})}
async function init(){try{state.me=await api('api/me');state.users=await api('api/users');await navigate('dashboard')}catch{login()}}
init();
